        public int Speed;
        public int Dexterity;
        public int Vitality;
        public int Wisdom;
        public ushort Level;
        public long Xp;
        public long XpGoal;
        public long Fame;

        public void Write(ByteWriter w)
        {
            w.WriteI32(Hp);
            w.WriteI32(MaxHp);
            w.WriteI32(Mp);
            w.WriteI32(MaxMp);
            w.WriteI32(Attack);
            w.WriteI32(Defense);
            w.WriteI32(Speed);
            w.WriteI32(Dexterity);
            w.WriteI32(Vitality);
            w.WriteI32(Wisdom);
            w.WriteU16(Level);
            w.WriteI64(Xp);
            w.WriteI64(XpGoal);
            w.WriteI64(Fame);
        }

        public static PlayerStats Read(ByteReader r)
        {
            var v = new PlayerStats();
            v.Hp = r.ReadI32();
            v.MaxHp = r.ReadI32();
            v.Mp = r.ReadI32();
            v.MaxMp = r.ReadI32();
            v.Attack = r.ReadI32();
            v.Defense = r.ReadI32();
            v.Speed = r.ReadI32();
            v.Dexterity = r.ReadI32();
            v.Vitality = r.ReadI32();
            v.Wisdom = r.ReadI32();
            v.Level = r.ReadU16();
            v.Xp = r.ReadI64();
            v.XpGoal = r.ReadI64();
            v.Fame = r.ReadI64();
            return v;
        }
    }

    /// <summary>The local player's item slots (item types, -1 = empty).</summary>
    public sealed class Inventory : IMessage
    {
        public MessageId Id => MessageId.Inventory;
        public List<int> Items;

        public void Write(ByteWriter w)
        {
            w.WriteListCount(Items.Count);
            foreach (var item in Items) w.WriteI32(item);
        }

        public static Inventory Read(ByteReader r)
        {
            var v = new Inventory();
            int n_items = r.ReadListCount();
            v.Items = new List<int>(Math.Min(n_items, r.Remaining));
            for (int i = 0; i < n_items; i++) v.Items.Add(r.ReadI32());
            return v;
        }
    }

    /// <summary>count projectiles fired together from position, the first at angle (radians), each next one angleStep further. Drawn by clients; hits are decided by the server alone.</summary>
    public sealed class ProjectileVolley : IMessage
    {
        public MessageId Id => MessageId.ProjectileVolley;
        public uint OwnerId;
        public bool OwnerIsEnemy;
        public ushort FirstBulletId;
        public Vec2 Position;
        public float Angle;
        public float AngleStep;
        public byte Count;
        public ProjectileSpec Spec;

        public void Write(ByteWriter w)
        {
            w.WriteU32(OwnerId);
            w.WriteBool(OwnerIsEnemy);
            w.WriteU16(FirstBulletId);
            Position.Write(w);
            w.WriteF32(Angle);
            w.WriteF32(AngleStep);
            w.WriteU8(Count);
            Spec.Write(w);
        }

        public static ProjectileVolley Read(ByteReader r)
        {
            var v = new ProjectileVolley();
            v.OwnerId = r.ReadU32();
            v.OwnerIsEnemy = r.ReadBool();
            v.FirstBulletId = r.ReadU16();
            v.Position = Vec2.Read(r);
            v.Angle = r.ReadF32();
            v.AngleStep = r.ReadF32();
            v.Count = r.ReadU8();
            v.Spec = ProjectileSpec.Read(r);
            return v;
        }
    }

    /// <summary>The local player's character died (permadeath). The server closes the session shortly after.</summary>
    public sealed class PlayerDied : IMessage
    {
        public MessageId Id => MessageId.PlayerDied;
        public string KilledBy;
        public ushort Level;
        public long Fame;

        public void Write(ByteWriter w)
        {
            w.WriteString(KilledBy);
            w.WriteU16(Level);
            w.WriteI64(Fame);
        }

        public static PlayerDied Read(ByteReader r)
        {
            var v = new PlayerDied();
            v.KilledBy = r.ReadString();
            v.Level = r.ReadU16();
            v.Fame = r.ReadI64();
            return v;
        }
    }

    public static class MessageCodec
    {
        public static string NameOf(ushort id)
        {
            switch (id)
            {
                case 1: return "Hello";
                case 2: return "Ping";
                case 3: return "LoadCharacter";
                case 4: return "CreateCharacter";
                case 5: return "MoveInput";
                case 6: return "Shoot";
                case 7: return "ChatSend";
                case 8: return "Escape";
                case 9: return "UsePortal";
                case 10: return "UseItem";
                case 11: return "InvSwap";
                case 12: return "InvDrop";
                case 101: return "HelloAck";
                case 102: return "Failure";
                case 103: return "Pong";
                case 104: return "WorldInfo";
                case 105: return "TileData";
                case 106: return "PlayerSpawned";
                case 107: return "Snapshot";
                case 108: return "ChatMessage";
                case 109: return "Notification";
                case 110: return "PlayerStats";
                case 111: return "Inventory";
                case 112: return "ProjectileVolley";
                case 113: return "PlayerDied";
                default: return "Unknown";
            }
        }

        /// <summary>Decode one payload sent by the client. Throws ProtocolException on bad data.</summary>
        public static IMessage DecodeClient(ushort id, ByteReader r)
        {
            IMessage m;
            switch (id)
            {
                case 1: m = Hello.Read(r); break;
                case 2: m = Ping.Read(r); break;
                case 3: m = LoadCharacter.Read(r); break;
                case 4: m = CreateCharacter.Read(r); break;
                case 5: m = MoveInput.Read(r); break;
                case 6: m = Shoot.Read(r); break;
                case 7: m = ChatSend.Read(r); break;
                case 8: m = Escape.Read(r); break;
                case 9: m = UsePortal.Read(r); break;
                case 10: m = UseItem.Read(r); break;
                case 11: m = InvSwap.Read(r); break;
                case 12: m = InvDrop.Read(r); break;
                case 101:
                case 102:
                case 103:
                case 104:
                case 105:
                case 106:
                case 107:
                case 108:
                case 109:
                case 110:
                case 111:
                case 112:
                case 113:
                    throw new ProtocolException("message " + id + " has the wrong direction");
                default: throw new ProtocolException("unknown message id " + id);
            }
            if (r.Remaining != 0) throw new ProtocolException("trailing bytes after message " + id);
            return m;
        }

        /// <summary>Decode one payload sent by the server. Throws ProtocolException on bad data.</summary>
        public static IMessage DecodeServer(ushort id, ByteReader r)
        {
            IMessage m;
            switch (id)
            {
                case 101: m = HelloAck.Read(r); break;
                case 102: m = Failure.Read(r); break;
                case 103: m = Pong.Read(r); break;
                case 104: m = WorldInfo.Read(r); break;
                case 105: m = TileData.Read(r); break;
                case 106: m = PlayerSpawned.Read(r); break;
                case 107: m = Snapshot.Read(r); break;
                case 108: m = ChatMessage.Read(r); break;
                case 109: m = Notification.Read(r); break;
                case 110: m = PlayerStats.Read(r); break;
                case 111: m = Inventory.Read(r); break;
                case 112: m = ProjectileVolley.Read(r); break;
                case 113: m = PlayerDied.Read(r); break;
                case 1:
                case 2:
                case 3:
                case 4:
                case 5:
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                case 11:
                case 12:
                    throw new ProtocolException("message " + id + " has the wrong direction");
                default: throw new ProtocolException("unknown message id " + id);
            }
            if (r.Remaining != 0) throw new ProtocolException("trailing bytes after message " + id);
            return m;
        }

    }

    /// <summary>Implement this on the client to receive every server message type.</summary>
    public interface IServerMessageHandler
    {
        void Handle(HelloAck message);
        void Handle(Failure message);
        void Handle(Pong message);
        void Handle(WorldInfo message);
        void Handle(TileData message);
        void Handle(PlayerSpawned message);
        void Handle(Snapshot message);
        void Handle(ChatMessage message);
        void Handle(Notification message);
        void Handle(PlayerStats message);
        void Handle(Inventory message);
        void Handle(ProjectileVolley message);
        void Handle(PlayerDied message);
    }

    public static class ServerMessageDispatcher
    {
        public static void Dispatch(IMessage message, IServerMessageHandler handler)
        {
            switch (message)
            {
                case HelloAck x: handler.Handle(x); break;
                case Failure x: handler.Handle(x); break;
                case Pong x: handler.Handle(x); break;
                case WorldInfo x: handler.Handle(x); break;
                case TileData x: handler.Handle(x); break;
                case PlayerSpawned x: handler.Handle(x); break;
                case Snapshot x: handler.Handle(x); break;
                case ChatMessage x: handler.Handle(x); break;
                case Notification x: handler.Handle(x); break;
                case PlayerStats x: handler.Handle(x); break;
                case Inventory x: handler.Handle(x); break;
                case ProjectileVolley x: handler.Handle(x); break;
                case PlayerDied x: handler.Handle(x); break;
                default: throw new ProtocolException("not a server message: " + message.Id);
            }
        }
    }
}
